async function seed() {
    const client = await pgPool.connect();
    try {
        await client.query("BEGIN");
        // Clear existing data
        await client.query("DELETE FROM statutory_audit_records");
        const now = new Date().toISOString();
        let count = 0;
        for (const loc of DATA) {
            for (const audit of loc.audits) {
                await client.query(`INSERT INTO statutory_audit_records (location_category, location_name, sort_order, audit_type, date_done, remarks, reference_no, created_at, updated_at)
           VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)`, [loc.locationCategory, loc.locationName, loc.sortOrder, audit.type, audit.dateDone ?? null, audit.remarks ?? null, audit.referenceNo ?? null, now, now]);
                count++;
            }
        }
        await client.query("COMMIT");
        console.log(`Seeded ${count} records across ${DATA.length} locations successfully!`);
    }
    catch (err) {
        await client.query("ROLLBACK").catch(() => { });
        console.error("Seed failed:", err);
        process.exit(1);
    }
    finally {
        client.release();
        await pgPool.end();
    }
}
seed();
